# Sources for the ambient lesson (lessons/sound-ambient.qmd) and the Ambient Generator (tools/ambient.qmd,
# apps/shared/lessons/ambient-kit.js). Read 2026-11-27 (Wikipedia only; the end of "Ambient music" was not read in full).
_L = ["lessons/sound-ambient.qmd"]
SOURCES = [
    wiki("Ambient music", "Ambient_music", _L, who="student", note="Eno popularised the term with Music for Airports; the liner-note quotation 'as ignorable as it is interesting'; La Monte Young and drone; San Francisco Tape Music Center (1962); Oliveros, deep listening (1988); Berlin School, Tangerine Dream, Klaus Schulze; ambient house, the Orb, Aphex Twin, chill-out rooms; Selected Ambient Works Volume II (1994)."),
    wiki("Ambient 1: Music for Airports", "Ambient_1:_Music_for_Airports", _L, who="student", note="Released February 1979 (liner notes dated 1978); first Eno album under the label ambient; tape loops of keyboards and voices at differing lengths; 2/1: vocal loops of disparate lengths, Eno started them running and let them configure."),
    wiki("Discreet Music", "Discreet_Music", _L, who="student", note="1975; Synthi AKS sequencer, two phrases of different lengths, graphic EQ, echo, two tape machines in a delay loop; the harp record played too quietly after Eno's accident (Judy Nylon disputes it)."),
    wiki("Furniture music", "Furniture_music", _L, who="student", note="Term coined by Erik Satie in 1917; second set premiered 1920 in Paris as intermission music."),
]
